using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true, DepartmentName = "Computer Science" },
        new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and associated algorithms for searching and sorting.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez is an expert in algorithm design with publications in top journals. He previously worked at Google Research.", IsFeatured = true, DepartmentName = "Computer Science" },
        new() { Id = 3, DepartmentId = 1, CourseCode = "CS 310", Title = "Database Systems", Description = "Design and implementation of database systems. Covers relational model, SQL, normalization, indexing, and transaction processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez specializes in distributed databases and has consulted for Fortune 500 companies on data architecture.", IsFeatured = false, DepartmentName = "Computer Science" },
        new() { Id = 4, DepartmentId = 1, CourseCode = "CS 440", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search, knowledge representation, machine learning, and neural networks.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Alan Turing Jr.", InstructorBio = "Dr. Turing is a leading researcher in machine learning with experience at DeepMind and OpenAI.", IsFeatured = true, DepartmentName = "Computer Science" },
        new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with over 20 years of teaching experience.", IsFeatured = true, DepartmentName = "Mathematics" },
        new() { Id = 6, DepartmentId = 2, CourseCode = "MATH 250", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research focuses on applied linear algebra and numerical methods.", IsFeatured = false, DepartmentName = "Mathematics" },
        new() { Id = 7, DepartmentId = 2, CourseCode = "MATH 320", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park has published over 40 papers in statistical methodology and serves as a consultant for biotech firms.", IsFeatured = false, DepartmentName = "Mathematics" },
        new() { Id = 8, DepartmentId = 3, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Richard Feynman III", InstructorBio = "Dr. Feynman is passionate about making physics accessible and engaging for all students.", IsFeatured = true, DepartmentName = "Physics" },
        new() { Id = 9, DepartmentId = 3, CourseCode = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Lab Fri 1:00–3:50 PM", InstructorName = "Dr. Lisa Chang", InstructorBio = "Dr. Chang conducts research in experimental physics and has contributed to projects at CERN.", IsFeatured = false, DepartmentName = "Physics" },
        new() { Id = 10, DepartmentId = 4, CourseCode = "ENG 110", Title = "Composition and Rhetoric", Description = "Develop effective writing skills through essay composition, argumentation, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. Katherine Mills", InstructorBio = "Prof. Mills is a published author and writing instructor with expertise in academic and creative writing.", IsFeatured = false, DepartmentName = "English" },
        new() { Id = 11, DepartmentId = 4, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and culture.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. Michael Brooks", InstructorBio = "Dr. Brooks is a specialist in 20th-century American literature and has authored two books on modernist poetry.", IsFeatured = false, DepartmentName = "English" },
        new() { Id = 12, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of global civilizations from ancient times through the medieval period, including Mesopotamia, Egypt, Greece, Rome, and China.", Credits = 3, Schedule = "Mon/Wed 3:00–4:15 PM", InstructorName = "Dr. Angela Davis-Smith", InstructorBio = "Dr. Davis-Smith is a historian specializing in comparative ancient civilizations with fieldwork experience across three continents.", IsFeatured = false, DepartmentName = "History" },
        new() { Id = 13, DepartmentId = 5, CourseCode = "HIST 280", Title = "Modern European History", Description = "Europe from the Enlightenment to the present: revolutions, industrialization, world wars, and European integration.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. Thomas Weber", InstructorBio = "Dr. Weber is a specialist in modern European political history and has published with Oxford University Press.", IsFeatured = false, DepartmentName = "History" },
    ];

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app this would persist to a database.
        return true;
    }
}

