@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p class="lead">Explore our departments, discover courses, and enroll for the upcoming semester.</p>
    </div>

    <section class="featured-section">
        <h2>Featured Courses</h2>
        <div class="course-grid">
            @foreach (var course in _featuredCourses)
            {
                <div class="course-card">
                    <span class="badge">@course.CourseCode</span>
                    <h3>@course.Title</h3>
                    <p>@course.Credits credits &middot; @course.DepartmentName</p>
                    <p class="description">@Truncate(course.Description, 100)</p>
                    <a href="/courses/@course.Id" class="btn">View Details</a>
                </div>
            }
        </div>
    </section>

    <section class="departments-section">
        <h2>Departments</h2>
        <div class="dept-grid">
            @foreach (var dept in _departments)
            {
                <div class="dept-card">
                    <h3>@dept.Name</h3>
                    <p>@dept.Description</p>
                    <a href="/courses?departmentId=@dept.Id" class="btn btn-outline">Browse Courses</a>
                </div>
            }
        </div>
    </section>

    <section class="cta-section">
        <h2>Ready to Enroll?</h2>
        <p>Submit your enrollment request to register for courses this semester.</p>
        <a href="/enroll" class="btn btn-large">Enroll Now</a>
    </section>
</div>

@code {
    private List<Course> _featuredCourses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetAllDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Browse Courses - University Course Catalog</PageTitle>

<div class="container">
    <h1>Browse Courses</h1>

    <div class="search-filters">
        <form method="get" action="/courses">
            <div class="filter-row">
                <input type="text" name="search" value="@_searchTerm" placeholder="Search courses, instructors..." class="search-input" />
                <select name="departmentId" class="filter-select">
                    <option value="">All Departments</option>
                    @foreach (var dept in _departments)
                    {
                        <option value="@dept.Id" selected="@(dept.Id == _departmentId)">@dept.Name</option>
                    }
                </select>
                <button type="submit" class="btn">Search</button>
            </div>
        </form>
    </div>

    @if (_courses.Count == 0)
    {
        <p class="no-results">No courses found matching your criteria.</p>
    }
    else
    {
        <p class="results-count">Showing @_courses.Count course(s)</p>
        <div class="course-list">
            @foreach (var course in _courses)
            {
                <div class="course-list-item">
                    <div class="course-list-info">
                        <span class="badge">@course.CourseCode</span>
                        <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                        <p>@course.DepartmentName &middot; @course.Credits credits &middot; @course.InstructorName</p>
                        <p class="schedule">@course.Schedule</p>
                    </div>
                    <a href="/courses/@course.Id" class="btn btn-outline">Details</a>
                </div>
            }
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Course> _courses = [];
    private List<Department> _departments = [];
    private string? _searchTerm;
    private int? _departmentId;

    protected override void OnInitialized()
    {
        _searchTerm = Search;
        _departmentId = DepartmentId;
        _departments = CatalogService.GetAllDepartments();
        _courses = CatalogService.SearchCourses(_searchTerm, _departmentId);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>
    <p>Complete the form below to submit your enrollment request.</p>

    @if (_submitted)
    {
        <div class="success-message">
            <h2>Request Submitted Successfully!</h2>
            <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received.</p>
            <p>You will receive confirmation via your university email.</p>
            <a href="/" class="btn">Return to Home</a>
        </div>
    }
    else
    {
        <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
            <AntiforgeryToken />
            <div class="form-group">
                <label for="studentName">Full Name</label>
                <input type="text" id="studentName" name="_model.StudentName" value="@_model.StudentName" required maxlength="100" class="form-input" />
                @if (_errors.ContainsKey("StudentName"))
                {
                    <span class="field-error">@_errors["StudentName"]</span>
                }
            </div>

            <div class="form-group">
                <label for="studentId">Student ID</label>
                <input type="text" id="studentId" name="_model.StudentId" value="@_model.StudentId" required pattern="^[A-Za-z0-9\-]+$" class="form-input" placeholder="e.g., STU-12345" />
                @if (_errors.ContainsKey("StudentId"))
                {
                    <span class="field-error">@_errors["StudentId"]</span>
                }
            </div>

            <div class="form-group">
                <label for="courseId">Course</label>
                <select id="courseId" name="_model.CourseId" required class="form-input">
                    <option value="">-- Select a Course --</option>
                    @foreach (var course in _courses)
                    {
                        <option value="@course.Id" selected="@(course.Id == _model.CourseId)">@course.CourseCode - @course.Title (@course.Credits credits)</option>
                    }
                </select>
                @if (_errors.ContainsKey("CourseId"))
                {
                    <span class="field-error">@_errors["CourseId"]</span>
                }
            </div>

            <button type="submit" class="btn btn-large">Submit Enrollment Request</button>
        </form>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();

    private List<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;
    private Dictionary<string, string> _errors = new();

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetAllCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        _errors.Clear();
        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(_model);
        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(_model, context, validationResults, true))
        {
            foreach (var result in validationResults)
            {
                foreach (var member in result.MemberNames)
                {
                    _errors[member] = result.ErrorMessage ?? "Invalid value.";
                }
            }
            return;
        }

        var course = CatalogService.GetCourse(_model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.CourseCode} - {course.Title}" : "Unknown Course";
        CatalogService.SubmitEnrollmentRequest(_model);
        _submitted = true;
    }
}

